import re as _re, math as _m
from itertools import permutations as _perm

_MIX = {"add": 5, "sub": 5, "mul": 5, "div": 5}
_OP = {"add": "+", "sub": "-", "mul": "*", "div": "/"}


def _val(text):
    t = str(text).replace('−', '-').replace('×', '*').replace('÷', '/').replace(',', '')
    m = _re.fullmatch(r'\s*(\d+)\s*([-+*/])\s*(\d+)\s*', t)
    if not m:
        return None
    a, op, b = int(m[1]), m[2], int(m[3])
    if op == '/' and b == 0:
        return None
    return a, op, b, {'+': a + b, '-': a - b, '*': a * b, '/': a / b}[op]


def _rev(a, op, b):
    return {'+': abs(a - b), '-': a + b, '*': a + b, '/': a - b}[op]


def _eq(x, y):
    try:
        return _m.isclose(float(x), float(y), rel_tol=1e-9, abs_tol=1e-9)
    except (TypeError, ValueError):
        return False


def _is_point(d, ans):
    return _eq(d, ans * 10) or _eq(d * 10, ans)


def _is_slip(d, ans):
    if not (_eq(d, round(float(d))) and _eq(ans, round(float(ans)))):
        return False
    s, t = str(int(round(float(d)))), str(int(round(float(ans))))
    if len(s) != len(t):
        return False
    diff = [(int(x), int(y)) for x, y in zip(s, t) if x != y]
    return len(diff) == 1 and abs(diff[0][0] - diff[0][1]) == 1


def _shape(it):
    return isinstance(it, dict) and {'kind', 'text', 'options', 'answer'} <= set(it) and isinstance(it['options'], (list, tuple)) and len(it['options']) == 4


def _all(items, f):
    return isinstance(items, list) and len(items) > 0 and all(_shape(it) and f(it) for it in items)


def _answer_ok(it):
    v = _val(it['text'])
    return v is not None and _OP[it['kind']] == v[1] and _eq(it['answer'], v[3])


def _whole_div(it):
    v = _val(it['text'])
    return it['kind'] != 'div' or (v is not None and _eq(v[3], round(v[3])))


def _once(it):
    o = list(it['options'])
    return sum(_eq(x, it['answer']) for x in o) == 1 and not any(_eq(o[i], o[j]) for i in range(4) for j in range(i + 1, 4))


def _positive(it):
    return all(float(x) > 0 for x in it['options'])


def _types_ok(it):
    v = _val(it['text'])
    if v is None:
        return False
    a, op, b, ans = v
    ds = [o for o in it['options'] if not _eq(o, ans)]
    if len(ds) != 3:
        return False
    checks = [lambda d: _eq(d, _rev(a, op, b)), lambda d: _is_point(d, ans), lambda d: _is_slip(d, ans)]
    return any(all(c(d) for c, d in zip(checks, p)) for p in _perm(ds))


def _counts(items):
    out = {}
    for it in items or []:
        out[it['kind']] = out.get(it['kind'], 0) + 1
    return out


def _key(items):
    return [(it['kind'], it['text'], [float(x) for x in it['options']], float(it['answer'])) for it in items]

