widget.solution:
import random


def reverse(kind, a, b):
    return {"add": abs(a - b), "sub": a + b, "mul": a + b, "div": a - b}[kind]


def point(rng, ans):
    return ans * 10 if rng.random() < 0.5 else ans / 10


def slip(rng, ans):
    s = str(ans)
    i = rng.randrange(len(s))
    d = int(s[i]) + rng.choice((1, -1))
    if d < 0 or d > 9 or (i == 0 and d == 0):
        d = int(s[i]) - (d - int(s[i]))
    return int(s[:i] + str(d) + s[i + 1:])


def operands(rng, kind):
    if kind == "add":
        return rng.randint(100, 999), rng.randint(100, 999)
    if kind == "sub":
        b = rng.randint(100, 998)
        return rng.randint(b + 1, 999), b
    if kind == "mul":
        return rng.randint(2, 12), rng.randint(12, 99)
    a, q = rng.randint(2, 12), rng.randint(12, 99)
    return a * q, a


def item(rng, kind):
    sign = {"add": "+", "sub": "−", "mul": "×", "div": "÷"}[kind]
    while True:
        a, b = operands(rng, kind)
        ans = {"add": a + b, "sub": a - b, "mul": a * b, "div": a // b}[kind]
        wrong = [reverse(kind, a, b), point(rng, ans), slip(rng, ans)]
        values = wrong + [ans]
        if min(values) > 0 and len(set(values)) == 4:
            break
    options = values[:]
    rng.shuffle(options)
    return {"kind": kind, "text": f"{a} {sign} {b}", "options": options, "answer": ans}


def battery_generator(seed, mix):
    rng = random.Random(seed)
    items = []
    for kind, count in mix.items():
        for _ in range(count):
            items.append(item(rng, kind))
    rng.shuffle(items)
    return items

